  assert.deepEqual(
    mergeCommercialFields(
      existingProduct,
      { affiliate_link: "", image_url: "   ", price_eur: undefined },
      false,
    ),
    {
      affiliate_link: "https://example.com/old",
      image_url: "https://example.com/old.jpg",
      price_eur: 12.99,
    },
  )

  assert.deepEqual(
    mergeCommercialFields(
      existingProduct,
      { affiliate_link: undefined, image_url: null, price_eur: undefined },
      true,
    ),
    {
      affiliate_link: null,
      image_url: null,
      price_eur: null,
    },
  )
})

